import{_ as t,o as r,c as o,a5 as e}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"YSB0075-批量压缩文件及文件夹压缩为压缩包","日期":"2026-04-11T00:00:00.000Z","修改日期":"2026-04-11T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Bat批处理"],"标签":["批量压缩","批量压缩文件","批量压缩文件夹","文件压缩为压缩包","文件夹压缩为压缩包"]},"headers":[],"relativePath":"md/Bat批处理/YSB0075-批量压缩文件及文件夹压缩为压缩包.md","filePath":"md/Bat批处理/YSB0075-批量压缩文件及文件夹压缩为压缩包.md"}'),n={name:"md/Bat批处理/YSB0075-批量压缩文件及文件夹压缩为压缩包.md"};function s(p,a,i,l,h,c){return r(),o("div",null,[...a[0]||(a[0]=[e('<h2 id="批量将程序所在文件夹下文件及文件夹分别压缩为压缩包" tabindex="-1">批量将程序所在文件夹下文件及文件夹分别压缩为压缩包 <a class="header-anchor" href="#批量将程序所在文件夹下文件及文件夹分别压缩为压缩包" aria-label="Permalink to &quot;批量将程序所在文件夹下文件及文件夹分别压缩为压缩包&quot;">​</a></h2><p>批量对程序所在目录下所有文件及文件夹进行压缩</p><p>1、将程序放在和需要压缩的文件夹及文件同一目录下双击运行程序，程序会自动将文件夹以文件夹名作为压缩包名的形式压缩</p><p>2、程序会自动将将文件名以压缩包名进行压缩</p><p>3、不支持添加压缩密码</p><h3 id="▶程序截图-可能随更新有些许变化" tabindex="-1"><strong>▶程序截图，可能随更新有些许变化</strong> <a class="header-anchor" href="#▶程序截图-可能随更新有些许变化" aria-label="Permalink to &quot;**▶程序截图，可能随更新有些许变化**&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250222191310174022279080463.png" alt=""></p><h3 id="▶【以下支持】" tabindex="-1"><strong>▶【以下支持】：</strong> <a class="header-anchor" href="#▶【以下支持】" aria-label="Permalink to &quot;**▶【以下支持】：**&quot;">​</a></h3><p>【1】、支持的文件格式：压缩为rar格式压缩包</p><p>【2】、是否支持子文件夹穿透：不支持</p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多压缩包文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有压缩包文件。</p><p>【操作方法】：将将程序放在A文件夹下，运行程序后，将A文件夹根目录下所有文件夹及文件分别压缩为rar格式压缩包，压缩包名分别以文件夹名或文件名命名。</p><h3 id="▶-winrar程序安装说明-这步必须操作" tabindex="-1">**▶ **winrar程序安装说明，这步必须操作： <a class="header-anchor" href="#▶-winrar程序安装说明-这步必须操作" aria-label="Permalink to &quot;**▶ **winrar程序安装说明，这步必须操作：&quot;">​</a></h3><p>注意：安装路径必须为此处：D:\\rar\\，**提示：**请提前在D盘创建文件夹：rar</p><p>如果没有D盘，则安装在C盘，然后修改代码部分即可：将D修改为C</p><h3 id="📑-bat程序下一步执行方法" tabindex="-1">📑 bat程序下一步执行方法 <a class="header-anchor" href="#📑-bat程序下一步执行方法" aria-label="Permalink to &quot;📑 bat程序下一步执行方法&quot;">​</a></h3><p>**▶ **使用时，<strong>键盘回车键（就是键盘上的 ENTER 键）</strong>“回车确认”是执行下一步的方法 ，</p><p>比如将路径复制到程序中后，回车键确认执行下一步，每一步输入后，回车键确认即可向下执行。</p><p><strong>▶ 注意：请先测试备份原文件再批量使用，以免造成不可逆损失！！！</strong></p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250222191525174022292517929.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>：建议win7及以上64位win操作系统，mac系统需要定制。</p><p><strong>注意事项：bat程序原理上是支持</strong>win32位系统的，但不能完全确定。</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：程序不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><p>📑 本工具下载地址</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1397.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1397.html</a></p>',27)])])}const g=t(n,[["render",s]]);export{_ as __pageData,g as default};
